//! 蓝色按钮 — generated by `lyco new`.
//! Behavior lives here; styling + [meta] live in `assets/components/蓝色按钮.toml`.

use ply_engine::prelude::*;

use crate::components::config::{self, 蓝色按钮Config};
use crate::theme;

fn cfg() -> 蓝色按钮Config {
    config::effective(
        config::Style::current().蓝色按钮,
        蓝色按钮Config::get(),
        蓝色按钮Config::merged,
    )
}

/// A 蓝色按钮 component.
pub fn 蓝色按钮(ui: &mut Ui<'_, ()>, label: &str) {
    let c = cfg();
    let theme = theme::theme();
    // Outer fit + inner grow wrapper (same as the library `button`): the inner
    // element carries the padding + CenterX alignment so the label centers
    // reliably within the box.
    ui.element()
        .width(fit!())
        .height(fixed!(theme.shapes.button_height))
        .children(|ui| {
            ui.element()
                .width(grow!())
                .height(grow!())
                .background_color(c.background.map(Color::from).unwrap_or(theme.colors.primary.into()))
                .corner_radius(c.radius.unwrap_or(theme.shapes.radius_sm))
                .layout(|l| {
                    // Symmetric padding + CenterX. `center_x_shift` only exists
                    // for fonts whose ink is genuinely asymmetric; it defaults to
                    // 0 and should stay 0 on most setups. 字号随生效缩放,墨迹
                    // 不对称量同理 —— 覆盖值已在 effective() 缩放过,勿再乘 px.
                    let pad = c.pad_x.unwrap_or(theme::px(16.0));
                    let (lp, rp) = if c.center_x.unwrap_or(true) {
                        let shift = c.center_x_shift.unwrap_or(0.0);
                        (pad - shift, pad + shift)
                    } else {
                        (pad, pad)
                    };
                    l.padding((0, rp as u16, 0, lp as u16))
                        .align(if c.center_x.unwrap_or(true) { CenterX } else { Left }, CenterY)
                })
                .children(|ui| {
                    // NOTE: do NOT set `t.alignment(AlignX::CenterX)` here. ply's
                    // text alignment is an OFFSET on top of the element's bbox
                    // (engine.rs `align_width - line_width`), and the layout above
                    // already centers the fit-width box once. Setting CenterX here
                    // double-centers → text shifts RIGHT by half the free space.
                    // The library button / copy button never set text alignment —
                    // that's the proven-correct pattern.
                    ui.text(label, |t| {
                        t.font_size(c.font_size.unwrap_or(theme.text.label_size))
                            .color(c.foreground.map(Color::from).unwrap_or(theme.colors.on_primary.into()))
                    });
                });
        });
}
